procedure:
Send PUT /api/documents/<documentId>/name
Headers: Authorization: Bearer <accessToken>; Content-Type: application/json
Body: { "fileName": "Tờ trình (bản cuối).pdf" }

Send PUT /api/documents/<documentId>/folder
Headers: Authorization: Bearer <accessToken>; Content-Type: application/json
Body: { "folderId": "<folderId>" }

Send POST /api/folders
Headers: Authorization: Bearer <accessToken>; Content-Type: application/json
Body: { "name": "Hồ sơ họp" }

Send PUT /api/folders/<folderId>/name
Headers: Authorization: Bearer <accessToken>; Content-Type: application/json
Body: { "name": "Hồ sơ quý 4" }

Send PUT /api/folders/<folderId>/parent
Headers: Authorization: Bearer <accessToken>; Content-Type: application/json
Body: { "parentId": "<targetFolderId>" }

Send POST /api/meetings/<meetingId>/documents
Headers: Authorization: Bearer <accessToken>; Content-Type: application/json
Body: { "documentIds": ["<libraryDocId1>", "<libraryDocId2>"] }

Send POST /api/meetings/<meetingId>/agenda/<agendaItemId>/documents
Headers: Authorization: Bearer <accessToken>; Content-Type: application/json
Body: { "documentIds": ["<meetingDocumentId1>", "<meetingDocumentId2>"] }

Send POST /api/meetings/<meetingId>/agenda/<agendaItemId>/documents/from-library
Headers: Authorization: Bearer <accessToken>; Content-Type: application/json
Body: { "documentIds": ["<libraryDocumentId>"] }

Send POST /api/meetings/<meetingId>/documents/<meetingDocumentId>/comments
Headers: Authorization: Bearer <accessToken>; Content-Type: application/json
Body: { "body": "Xem lại số liệu trang này", "pageNumber": 3, "parentCommentId": null }

Send POST /api/meetings/<meetingId>/documents/<meetingDocumentId>/read-confirmation
Headers: Authorization: Bearer <accessToken>; Content-Type: application/json
Body: { "lastPageReached": true }
